// Construye el prompt para sugerencias de IA (descripciones, hashtags, matching).
const task = $input.all()[0].json;
const t = task.tarea;
const p = (t && t.payload) || {};
let instruccion = '';
let texto = '';
if (t.tipo === 'sugerir_descripcion') {
  instruccion = 'Eres un redactor experto en adopcion de mascotas. Con los datos de la mascota escribe una descripcion atractiva y empatica en espanol (3-5 frases) y requisitos de adopcion claros. Responde SOLO JSON: {"descripcion": "...", "requisitos": "..."}.\n\n';
  texto = 'Nombre: ' + (p.nombre || '') + '\nTipo: ' + (p.tipo || '') + '\nRaza: ' + (p.raza || '') + '\nEdad: ' + (p.edad || '') + '\nPersonalidad: ' + (p.personalidad || '') + '\nSalud: ' + (p.salud || '');
} else if (t.tipo === 'sugerir_hashtags') {
  instruccion = 'Genera 5-8 hashtags relevantes en espanol para una publicacion de Adoptify. Responde SOLO JSON: {"hashtags": ["#...", ...]}.\n\n';
  texto = (p.titulo || '') + '\n' + (p.contenido || '');
} else {
  instruccion = 'Analiza los datos y responde SOLO JSON con la sugerencia mas adecuada.\n\n';
  texto = JSON.stringify(p);
}
return [{ json: { tipo: t.tipo, tarea_id: t.id, prompt: instruccion + texto } }];

// Extrae y valida el JSON de Gemini y arma el resultado de la tarea.
const r = $input.all()[0].json;
const tareaId = $('Construir texto').first().json.tarea_id;
let texto = '';
try {
  texto = r.candidates[0].content.parts[0].text;
} catch (e) {
  texto = '';
}
if (!texto) {
  return [{ json: { tarea_id: tareaId, resultado: null, error: 'Respuesta vacia de Gemini' } }];
}
texto = texto.trim();
if (texto.startsWith('```json')) texto = texto.slice(7);
else if (texto.startsWith('```')) texto = texto.slice(3);
if (texto.endsWith('```')) texto = texto.slice(0, -3);
try {
  const resultado = JSON.parse(texto.trim());
  return [{ json: { tarea_id: tareaId, resultado, error: null } }];
} catch (e) {
  return [{ json: { tarea_id: tareaId, resultado: null, error: 'JSON invalido devuelto por Gemini' } }];
}
